package MovableCircle;

/**
 *
 * @author GIA KINH
 */
public class MovableCircle implements Movable{
    private int radius;
    private MovablePoint center;

    public MovableCircle() {
    }

    public MovableCircle(int radius, MovablePoint center) {
        this.radius = radius;
        this.center = center;
    }

    public MovableCircle(int x, int y, int xSpeed, int ySpeed,int radius) {
        this.radius = radius;
        this.center = new MovablePoint(x, y, xSpeed, ySpeed);
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public MovablePoint getCenter() {
        return center;
    }

    public void setCenter(MovablePoint center) {
        this.center = center;
    }

    @Override
    public String toString() {
        return  center + ",radius=" + radius;
    }

    @Override
    public void moveUp() {
       this.center.setY(this.center.getY()-this.center.getySpeed());
    }

    @Override
    public void moveDown() {
        this.center.setY(this.center.getY()+this.center.getySpeed());
    }

    @Override
    public void moveLeft() {
        this.center.setX(this.center.getX()-this.center.getxSpeed());
    }

    @Override
    public void moveRight() {
        this.center.setX(this.center.getX()+this.center.getxSpeed());
    } 
}

package MovableCircle;

/**
 * A circle whose center is a MovablePoint, implementing Movable.
 */
public class MovableCircle implements Movable {
    private int radius;
    private MovablePoint center;

    public MovableCircle() {
    }

    public MovableCircle(int radius, MovablePoint center) {
        this.radius = radius;
        this.center = center;
    }

    public MovableCircle(int x, int y, int xSpeed, int ySpeed, int radius) {
        this.radius = radius;
        this.center = new MovablePoint(x, y, xSpeed, ySpeed);
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public MovablePoint getCenter() {
        return center;
    }

    public void setCenter(MovablePoint center) {
        this.center = center;
    }

    @Override
    public String toString() {
        return center + ",radius=" + radius;
    }

    @Override
    public void moveUp() {
        center.setY(center.getY() - center.getySpeed());
    }

    @Override
    public void moveDown() {
        center.setY(center.getY() + center.getySpeed());
    }

    @Override
    public void moveLeft() {
        center.setX(center.getX() - center.getxSpeed());
    }

    @Override
    public void moveRight() {
        center.setX(center.getX() + center.getxSpeed());
    }
}

