package Resizable;

/**
 *
 * @author GIA KINH
 */
public class ResizableCircle extends Circle implements Resizable{

    public ResizableCircle(double radius) {
        super(radius);
    }

    public ResizableCircle() {
    }

    @Override
    public String toString() {
        return "ResizableCircle[" + super.toString() +']';
    }



    @Override
    public void resize(int percent) {
        radius *= percent/100;
    }

}

package Resizable;

/**
 * A circle that can be resized by a percentage.
 */
public class ResizableCircle extends Circle implements Resizable {

    public ResizableCircle(double radius) {
        super(radius);
    }

    public ResizableCircle() {
    }

    @Override
    public String toString() {
        return "ResizableCircle[" + super.toString() + ']';
    }

    @Override
    public void resize(int percent) {
        // mirrors the original's integer-division bug: percent/100 truncates to 0
        radius *= percent / 100;
    }
}

