/**
 * Reads student names and title-cases each word before storing them.
 */
public class Part3 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ArrayList<Student> students = new ArrayList<>();
        System.out.print("Enter number student: ");
        int n = scanner.nextInt();
        scanner.nextLine();
        for (int i = 0; i < n; i++) {
            System.out.print("Enter name student " + (i + 1) + ": ");
            String rawName = scanner.nextLine();
            rawName = rawName.trim().replaceAll("\\s+", " ");
            StringTokenizer tokenizer = new StringTokenizer(rawName, " ");
            StringBuilder titled = new StringBuilder();
            while (tokenizer.hasMoreTokens()) {
                String part = tokenizer.nextToken();
                titled.append(part.substring(0, 1).toUpperCase()).append(part.substring(1)).append(" ");
            }
            students.add(new Student(titled.toString().trim()));
        }
        for (Student student : students) {
            System.out.println(student.toString());
        }
    }
}

