package player;

/**
 *
 * @author GIA KINH
 */
public class PlayerIncome extends Player implements Tax{

    private double income;

    public PlayerIncome(double income) {
        this.income = income;
    }

    public PlayerIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public PlayerIncome() {
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }




    @Override
    public void displayDetails() {
        System.out.println("Name player: "+super.getName());
        System.out.println("Salary: " + (this.income - this.calculateTax())+ "$");
        System.out.println("Tax: " + this.calculateTax()+"$");
    }

    @Override
    public double calculateTax() {
        if(this.income<=10000){
            return this.income*15/100;
        }else if(this.income <=20000){
            return this.income * 20 / 100;
        }else{
            return this.income * 30 / 100;
        }
    }

}

package player;

/**
 * A player with income subject to a tiered tax.
 */
public class PlayerIncome extends Player implements Tax {

    private double income;

    public PlayerIncome(double income) {
        this.income = income;
    }

    public PlayerIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public PlayerIncome() {
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Salary: " + (income - calculateTax()) + "$");
        System.out.println("Tax: " + calculateTax() + "$");
    }

    @Override
    public double calculateTax() {
        if (income <= 10000) {
            return income * 15 / 100;
        } else if (income <= 20000) {
            return income * 20 / 100;
        } else {
            return income * 30 / 100;
        }
    }
}

