package player;

/**
 *
 * @author GIA KINH
 */
public class TournamentIncome extends Player implements GradeBonus {

    private int totalMatches;
    private int battle;
    private double[] points;
    private double income;

    public TournamentIncome(int totalMatches, int battle, double[] points, double income) {
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points, double income, String name) {
        super(name);
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points) {
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public TournamentIncome() {
    }

    public int getTotalMatches() {
        return totalMatches;
    }

    public void setTotalMatches(int totalMatches) {
        this.totalMatches = totalMatches;
    }

    public int getBattle() {
        return battle;
    }

    public void setBattle(int battle) {
        this.battle = battle;
    }

    public double[] getPoints() {
        return points;
    }

    public void setPoints(double[] points) {
        this.points = points;
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + super.getName());
        System.out.println("Grade bonus: " + this.calculateGradeBonus() + "%");
        System.out.println("Income: " + this.income + "$");
    }

    @Override
    public double calculateGradeBonus() {
        double totalPoint = 0;
        double money = 1000000;
        if (points != null) {
            for (double i : points) {
                totalPoint += i;
            }
        }else{
            System.out.println("Please enter points");
            return 0;
        }
        if (totalPoint < this.totalMatches * 100 * 0.3) {
            return GRADE_D_BONUS_PERCENT*money/100;
        } else if (totalPoint < this.totalMatches * 100 * 0.4) {
            return GRADE_C_BONUS_PERCENT*money/100;
        } else if (totalPoint < this.totalMatches * 100 * 0.5) {
            return GRADE_B_BONUS_PERCENT*money/100;
        } else {
            return GRADE_A_BONUS_PERCENT*money/100;
        }
    }

}

package player;

/**
 * A player's tournament performance and resulting grade bonus.
 */
public class TournamentIncome extends Player implements GradeBonus {

    private int totalMatches;
    private int battle;
    private double[] points;
    private double income;

    public TournamentIncome(int totalMatches, int battle, double[] points, double income) {
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points, double income, String name) {
        super(name);
        this.income = income;
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(int totalMatches, int battle, double[] points) {
        this.totalMatches = totalMatches;
        this.battle = battle;
        this.points = points;
    }

    public TournamentIncome(double income, String name) {
        super(name);
        this.income = income;
    }

    public TournamentIncome() {
    }

    public int getTotalMatches() {
        return totalMatches;
    }

    public void setTotalMatches(int totalMatches) {
        this.totalMatches = totalMatches;
    }

    public int getBattle() {
        return battle;
    }

    public void setBattle(int battle) {
        this.battle = battle;
    }

    public double[] getPoints() {
        return points;
    }

    public void setPoints(double[] points) {
        this.points = points;
    }

    public double getIncome() {
        return income;
    }

    public void setIncome(double income) {
        this.income = income;
    }

    @Override
    public void displayDetails() {
        System.out.println("Name player: " + getName());
        System.out.println("Grade bonus: " + calculateGradeBonus() + "%");
        System.out.println("Income: " + income + "$");
    }

    @Override
    public double calculateGradeBonus() {
        double totalPoint = 0;
        double money = 1000000;
        if (points == null) {
            System.out.println("Please enter points");
            return 0;
        }
        for (double point : points) {
            totalPoint += point;
        }
        if (totalPoint < totalMatches * 100 * 0.3) {
            return GRADE_D_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.4) {
            return GRADE_C_BONUS_PERCENT * money / 100;
        } else if (totalPoint < totalMatches * 100 * 0.5) {
            return GRADE_B_BONUS_PERCENT * money / 100;
        } else {
            return GRADE_A_BONUS_PERCENT * money / 100;
        }
    }
}

